CREATE TABLE ai_support_portfolio_demo.demo_submission_history(event_key CHAR(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,owner_key CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,outcome ENUM('REJECTED','PROCESSED','PENDING_REVIEW','PROCESSING_FAILED','PROCESSING','UNCONFIRMED') NOT NULL,http_status SMALLINT UNSIGNED NOT NULL,error_code VARCHAR(64) NULL,ticket_ref CHAR(10) NULL,ticket_status VARCHAR(32) NULL,created_at DATETIME(3) NOT NULL,INDEX owner_history(owner_key,created_at),INDEX history_expiry(created_at),CHECK(http_status BETWEEN 100 AND 599)) ENGINE=InnoDB;
